-- ===========================================================================
-- Part 2: CHECK constraints and triggers (hand-written)
-- ===========================================================================

-- Codes are lower-case identifiers ("telegram", "border_journey"). A format
-- check, not a fixed list, so new providers, games and modes need no
-- migration.

-- user_profiles
ALTER TABLE "user_profiles"
    ADD CONSTRAINT "user_profiles_display_name_not_blank"
        CHECK ("display_name" IS NULL OR btrim("display_name") <> '');

-- auth_identities
ALTER TABLE "auth_identities"
    ADD CONSTRAINT "auth_identities_provider_format"
        CHECK ("provider" ~ '^[a-z][a-z0-9_]*$'),
    ADD CONSTRAINT "auth_identities_provider_user_id_not_blank"
        CHECK (btrim("provider_user_id") <> ''),
    ADD CONSTRAINT "auth_identities_provider_data_is_object"
        CHECK ("provider_data" IS NULL OR jsonb_typeof("provider_data") = 'object');

-- games
ALTER TABLE "games"
    ADD CONSTRAINT "games_code_format"
        CHECK ("code" ~ '^[a-z][a-z0-9_]*$'),
    ADD CONSTRAINT "games_platform_format"
        CHECK ("platform" ~ '^[a-z][a-z0-9_]*$');

-- game_modes
ALTER TABLE "game_modes"
    ADD CONSTRAINT "game_modes_code_format"
        CHECK ("code" ~ '^[a-z][a-z0-9_]*$'),
    ADD CONSTRAINT "game_modes_difficulty_format"
        CHECK ("difficulty" IS NULL OR "difficulty" ~ '^[a-z][a-z0-9_]*$'),
    ADD CONSTRAINT "game_modes_rounds_per_session_positive"
        CHECK ("rounds_per_session" > 0),
    -- Must name a game_results column.
    ADD CONSTRAINT "game_modes_best_metric_valid"
        CHECK ("best_metric" IN ('score', 'correct_count', 'stars')),
    ADD CONSTRAINT "game_modes_config_is_object"
        CHECK (jsonb_typeof("config") = 'object');

-- game_sessions
ALTER TABLE "game_sessions"
    ADD CONSTRAINT "game_sessions_client_platform_format"
        CHECK ("client_platform" ~ '^[a-z][a-z0-9_]*$'),
    -- ended_at is set exactly when the session is no longer in progress.
    ADD CONSTRAINT "game_sessions_ended_at_matches_status"
        CHECK (("status" = 'in_progress') = ("ended_at" IS NULL)),
    ADD CONSTRAINT "game_sessions_ended_after_started"
        CHECK ("ended_at" IS NULL OR "ended_at" >= "started_at");

-- game_results
ALTER TABLE "game_results"
    ADD CONSTRAINT "game_results_score_non_negative"
        CHECK ("score" >= 0),
    ADD CONSTRAINT "game_results_total_rounds_positive"
        CHECK ("total_rounds" > 0),
    ADD CONSTRAINT "game_results_correct_count_range"
        CHECK ("correct_count" BETWEEN 0 AND "total_rounds"),
    -- Border journey: at most 3 stars per journey.
    ADD CONSTRAINT "game_results_stars_range"
        CHECK ("stars" IS NULL OR "stars" BETWEEN 0 AND 3 * "total_rounds"),
    ADD CONSTRAINT "game_results_best_streak_range"
        CHECK ("best_streak" IS NULL OR "best_streak" BETWEEN 0 AND "correct_count"),
    ADD CONSTRAINT "game_results_xp_earned_non_negative"
        CHECK ("xp_earned" IS NULL OR "xp_earned" >= 0),
    ADD CONSTRAINT "game_results_duration_ms_non_negative"
        CHECK ("duration_ms" IS NULL OR "duration_ms" >= 0),
    ADD CONSTRAINT "game_results_details_is_object"
        CHECK ("details" IS NULL OR jsonb_typeof("details") = 'object');

-- outbox_events
ALTER TABLE "outbox_events"
    ADD CONSTRAINT "outbox_events_aggregate_type_format"
        CHECK ("aggregate_type" ~ '^[a-z][a-z0-9_]*$'),
    -- Dotted lower-case name, e.g. "game_result.recorded".
    ADD CONSTRAINT "outbox_events_event_type_format"
        CHECK ("event_type" ~ '^[a-z][a-z0-9_]*(\.[a-z][a-z0-9_]*)+$'),
    ADD CONSTRAINT "outbox_events_event_version_positive"
        CHECK ("event_version" >= 1),
    ADD CONSTRAINT "outbox_events_attempts_non_negative"
        CHECK ("attempts" >= 0),
    ADD CONSTRAINT "outbox_events_payload_is_object"
        CHECK (jsonb_typeof("payload") = 'object'),
    ADD CONSTRAINT "outbox_events_published_at_matches_status"
        CHECK (("status" = 'published') = ("published_at" IS NOT NULL));

-- ---------------------------------------------------------------------------
-- Trigger: a completed session stays completed.
-- Its result is final, so the session can't be reopened or abandoned.
-- ---------------------------------------------------------------------------
CREATE FUNCTION "game_sessions_completed_is_final"() RETURNS trigger
LANGUAGE plpgsql AS $$
BEGIN
    IF OLD."status" = 'completed' AND NEW."status" <> 'completed' THEN
        RAISE EXCEPTION 'game session % is completed and cannot change status to %',
            OLD."id", NEW."status"
            USING ERRCODE = 'check_violation';
    END IF;
    RETURN NEW;
END;
$$;

CREATE TRIGGER "game_sessions_completed_is_final"
    BEFORE UPDATE OF "status" ON "game_sessions"
    FOR EACH ROW EXECUTE FUNCTION "game_sessions_completed_is_final"();

-- ---------------------------------------------------------------------------
-- Trigger: results belong to completed sessions only.
-- Also copies the session's ended_at into completed_at, so the two never
-- disagree.
-- ---------------------------------------------------------------------------
CREATE FUNCTION "game_results_require_completed_session"() RETURNS trigger
LANGUAGE plpgsql AS $$
DECLARE
    session_status "game_session_status";
    session_ended_at timestamptz;
BEGIN
    SELECT "status", "ended_at" INTO session_status, session_ended_at
    FROM "game_sessions" WHERE "id" = NEW."session_id";

    -- A missing session is reported by the foreign key instead.
    IF FOUND AND session_status <> 'completed' THEN
        RAISE EXCEPTION 'game session % is %, results can only be recorded for completed sessions',
            NEW."session_id", session_status
            USING ERRCODE = 'check_violation';
    END IF;

    IF FOUND THEN
        NEW."completed_at" := session_ended_at;
    END IF;
    RETURN NEW;
END;
$$;

CREATE TRIGGER "game_results_require_completed_session"
    BEFORE INSERT ON "game_results"
    FOR EACH ROW EXECUTE FUNCTION "game_results_require_completed_session"();

-- ---------------------------------------------------------------------------
-- Trigger: results are immutable history.
-- A better score is a new row, never an edit. The only allowed change is
-- user_id, which moves with its session when two accounts are merged
-- (ON UPDATE CASCADE from game_sessions). Deleting a user still cascades.
-- ---------------------------------------------------------------------------
CREATE FUNCTION "game_results_immutable"() RETURNS trigger
LANGUAGE plpgsql AS $$
BEGIN
    IF (to_jsonb(NEW) - 'user_id') IS DISTINCT FROM (to_jsonb(OLD) - 'user_id') THEN
        RAISE EXCEPTION 'game result % is immutable; only user_id may change (account merge)',
            OLD."id"
            USING ERRCODE = 'check_violation';
    END IF;
    RETURN NEW;
END;
$$;

CREATE TRIGGER "game_results_immutable"
    BEFORE UPDATE ON "game_results"
    FOR EACH ROW EXECUTE FUNCTION "game_results_immutable"();
